             }

             Ok(quote! {
                 #inner_macro_path!(
                     #op_name,
                     #atomic,
                     (#(#operands),*),
                     #prev,
                     #next,
                     #ret,
                     #ghost_name,
                     #block
                 )
             })
         }
     }
